commands.command:
set -eu
cat > /etc/nginx/sites-available/https8443 <<'ANTRIEB_EOF'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name _;

    ssl_certificate     /etc/nginx/tls8443/server.crt;
    ssl_certificate_key /etc/nginx/tls8443/server.key;
    ssl_protocols TLSv1.2 TLSv1.3;

    location / {
        default_type text/plain;
        return 200 "node1 HTTPS service is healthy\n";
    }
}
ANTRIEB_EOF
ln -sfn /etc/nginx/sites-available/https8443 /etc/nginx/sites-enabled/https8443
rm -f /etc/nginx/sites-enabled/default
nginx -t
systemctl restart nginx
systemctl enable nginx
systemctl is-active nginx
ss -ltnp '( sport = :8443 )'
curl --fail --silent --show-error --cacert /etc/nginx/tls8443/server.crt "https://$NODE_IP:8443/"
